proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    // Prove the validity by unfolding the definitions of `valid` and `implies`.
    assert(forall |ex: Execution<T>| {
        if always(p.and(q)).satisfied_by(ex) {
            // Unfold the definition of `always` at this execution.
            reveal(always(p.and(q)).satisfied_by(ex));
            // At this point Verus should know: forall i, (p.and(q)).satisfied_by(ex.suffix(i)).
            // Unfold the target `always(p).and(always(q)).satisfied_by(ex)`.
            reveal(always(p).and(always(q)).satisfied_by(ex));
            assert(always(p).and(always(q)).satisfied_by(ex));
        }
        true
    });
}

